using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public static class TestHelpers
{
    public static SchoolContext CreateInMemoryContext(string? dbName = null)
    {
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
            .Options;
        var context = new SchoolContext(options);
        return context;
    }

    public static SchoolContext CreateSeededContext(string? dbName = null)
    {
        var context = CreateInMemoryContext(dbName);
        SeedData(context);
        return context;
    }

    public static void SeedData(SchoolContext context)
    {
        var instructor1 = new Instructor
        {
            ID = 1,
            LastName = "Abercrombie",
            FirstMidName = "Kim",
            HireDate = DateTime.Parse("1995-03-11"),
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { Location = "Smith 17" }
        };
        var instructor2 = new Instructor
        {
            ID = 2,
            LastName = "Fakhouri",
            FirstMidName = "Fadi",
            HireDate = DateTime.Parse("2002-07-06"),
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.AddRange(instructor1, instructor2);

        var dept1 = new Department
        {
            DepartmentID = 1,
            Name = "English",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = 1
        };
        var dept2 = new Department
        {
            DepartmentID = 2,
            Name = "Mathematics",
            Budget = 100000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = 2
        };
        context.Departments.AddRange(dept1, dept2);

        var course1 = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            Department = dept1,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };
        var course2 = new Course
        {
            CourseID = 4022,
            Title = "Microeconomics",
            Credits = 3,
            DepartmentID = 2,
            Department = dept2,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Courses.AddRange(course1, course2);

        var student1 = new Student
        {
            ID = 10,
            LastName = "Alexander",
            FirstMidName = "Carson",
            EnrollmentDate = DateTime.Parse("2010-09-01"),
            Enrollments = new List<Enrollment>()
        };
        var student2 = new Student
        {
            ID = 11,
            LastName = "Alonso",
            FirstMidName = "Meredith",
            EnrollmentDate = DateTime.Parse("2012-09-01"),
            Enrollments = new List<Enrollment>()
        };
        var student3 = new Student
        {
            ID = 12,
            LastName = "Anand",
            FirstMidName = "Arturo",
            EnrollmentDate = DateTime.Parse("2013-09-01"),
            Enrollments = new List<Enrollment>()
        };
        context.Students.AddRange(student1, student2, student3);

        var enrollment1 = new Enrollment { EnrollmentID = 1, CourseID = 1050, StudentID = 10, Grade = Grade.A, Course = course1, Student = student1 };
        context.Enrollments.Add(enrollment1);
        student1.Enrollments.Add(enrollment1);
        course1.Enrollments.Add(enrollment1);

        // CourseAssignment
        var ca = new CourseAssignment { CourseID = 1050, InstructorID = 1, Course = course1, Instructor = instructor1 };
        context.CourseAssignments.Add(ca);
        instructor1.CourseAssignments.Add(ca);
        course1.CourseAssignments.Add(ca);

        context.SaveChanges();
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests
{
    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotification()
    {
        using var sut = new NotificationService();

        sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        var result = sut.ReceiveNotification();
        Assert.NotNull(result);
        Assert.Equal("Student", result.EntityType);
        Assert.Equal("1", result.EntityId);
        Assert.Equal("CREATE", result.Operation);
        Assert.Contains("John Doe", result.Message);
        Assert.Contains("created", result.Message);
        Assert.Equal("Admin", result.CreatedBy);
        Assert.False(result.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        using var sut = new NotificationService();

        sut.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");

        var result = sut.ReceiveNotification();
        Assert.NotNull(result);
        Assert.Contains("ID: 42", result.Message);
        Assert.Contains("updated", result.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        using var sut = new NotificationService();

        sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var result = sut.ReceiveNotification();
        Assert.NotNull(result);
        Assert.Equal("System", result.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        using var sut = new NotificationService();

        sut.SendNotification("Department", "5", "Engineering", operation);

        var result = sut.ReceiveNotification();
        Assert.NotNull(result);
        Assert.Contains(expectedVerb, result.Message);
        Assert.Contains("Engineering", result.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        using var sut = new NotificationService();

        var result = sut.ReceiveNotification();

        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleSends_ReturnsFIFOOrder()
    {
        using var sut = new NotificationService();

        sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = sut.ReceiveNotification();
        var second = sut.ReceiveNotification();

        Assert.Contains("First", first!.Message);
        Assert.Contains("Second", second!.Message);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        using var sut = new NotificationService();

        // MarkAsRead is a no-op for in-memory implementation
        var exception = Record.Exception(() => sut.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var sut = new NotificationService();
        var exception = Record.Exception(() => sut.Dispose());
        Assert.Null(exception);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(21, result[0]);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FirstPageWithMore_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_WhenNotEvenlyDivisible()
    {
        var source = Enumerable.Range(1, 11).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(2, result.TotalPages);
    }
}

