+        using var sut = new NotificationService();
+
+        sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
+        sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
+
+        var first = sut.ReceiveNotification();
+        var second = sut.ReceiveNotification();
+
+        Assert.Contains("First", first!.Message);
+        Assert.Contains("Second", second!.Message);
+    }
+
+    [Fact]
+    public void MarkAsRead_DoesNotThrow()
+    {
+        using var sut = new NotificationService();
+
+        // MarkAsRead is a no-op for in-memory implementation
+        var exception = Record.Exception(() => sut.MarkAsRead(999));
+        Assert.Null(exception);
+    }
+
