using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Instructors);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var result = _controller.Index(1, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Chemistry", model.Courses.First().Title);
    }

    [Fact]
    public void Index_WithInstructorIdAndCourseId_PopulatesEnrollments()
    {
        var result = _controller.Index(1, 1050) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    [Fact]
    public void Details_ValidId_ReturnsInstructor()
    {
        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithCoursesData()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(instructor.CourseAssignments);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Create_Post_ValidModel_NoCourses_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            LastName = "NewInstr",
            FirstMidName = "Test",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Instructors.Count());
    }

    [Fact]
    public void Create_Post_ValidModel_WithCourses_AddsCourseAssignments()
    {
        var instructor = new Instructor
        {
            LastName = "NewInstr",
            FirstMidName = "Test",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };
        var selectedCourses = new[] { "1050", "4022" };

        var result = _controller.Create(instructor, selectedCourses) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal(2, instructor.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            CourseAssignments = new List<CourseAssignment>(),
            HireDate = DateTime.Today
        };

        var result = _controller.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCoursesData()
    {
        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndClearsDepartmentAdmin()
    {
        // Instructor 1 is administrator of department 1
        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(_context.Instructors);

        // Department administrator should be cleared
        var dept = _context.Departments.Find(1);
        Assert.Null(dept!.InstructorID);
    }
}

