public void Edit_Post_ValidModel_RedirectsToIndex()
{
    // Create a fresh context without seeded data to avoid tracking conflicts
    var dbName = Guid.NewGuid().ToString();
    var options = new Microsoft.EntityFrameworkCore.DbContextOptionsBuilder<SchoolContext>()
        .UseInMemoryDatabase(databaseName: dbName)
        .Options;
    var context = new SchoolContext(options);

    // Add a student directly
    var existingStudent = new Student
    {
        ID = 10,
        LastName = "Alexander",
        FirstMidName = "Carson",
        EnrollmentDate = DateTime.Parse("2010-09-01")
    };
    context.Students.Add(existingStudent);
    context.SaveChanges();
    context.ChangeTracker.Clear();

    var controller = new StudentsController(context);
    var updatedStudent = new Student
    {
        ID = 10,
        LastName = "UpdatedLast",
        FirstMidName = "Carson",
        EnrollmentDate = DateTime.Parse("2010-09-01")
    };

    var result = controller.Edit(updatedStudent) as RedirectToActionResult;

    Assert.NotNull(result);
    Assert.Equal("Index", result.ActionName);
    controller.Dispose();
    context.Dispose();
}

