[Fact]
public void Index_WithInstructorIdAndCourseId_SetsViewBagValues()
{
    // Use a minimal context to avoid InMemory provider duplication issues with deep Includes
    var dbName = Guid.NewGuid().ToString();
    var options = new Microsoft.EntityFrameworkCore.DbContextOptionsBuilder<SchoolContext>()
        .UseInMemoryDatabase(databaseName: dbName)
        .Options;
    var context = new SchoolContext(options);

    var instructor = new Instructor
    {
        ID = 1,
        LastName = "Test",
        FirstMidName = "Instr",
        HireDate = DateTime.Parse("2000-01-01"),
        CourseAssignments = new List<CourseAssignment>()
    };
    context.Instructors.Add(instructor);

    var course = new Course
    {
        CourseID = 100,
        Title = "TestCourse",
        Credits = 3,
        DepartmentID = 0,
        Enrollments = new List<Enrollment>(),
        CourseAssignments = new List<CourseAssignment>()
    };
    context.Courses.Add(course);

    var ca = new CourseAssignment { InstructorID = 1, CourseID = 100 };
    context.CourseAssignments.Add(ca);

    var student = new Student { ID = 50, LastName = "S", FirstMidName = "T", EnrollmentDate = DateTime.Today };
    context.Students.Add(student);

    var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 100, StudentID = 50 };
    context.Enrollments.Add(enrollment);

    context.SaveChanges();
    context.ChangeTracker.Clear();

    var controller = new InstructorsController(context);
    var result = controller.Index(1, 100) as ViewResult;

    Assert.NotNull(result);
    Assert.Equal(1, (int)controller.ViewBag.InstructorID);
    Assert.Equal(100, (int)controller.ViewBag.CourseID);
    controller.Dispose();
    context.Dispose();
}

